import struct

with open("{TARGET}", "rb") as f:
    data = f.read()

def vaddr_to_fileoff(vaddr):
    # Based on LOAD segments
    if 0x400000 <= vaddr < 0x400000 + 0xb10:
        return vaddr - 0x400000
    elif 0x401000 <= vaddr < 0x401000 + 0xad1:
        return vaddr - 0x401000 + 0x1000
    elif 0x402000 <= vaddr < 0x402000 + 0x66b:
        return vaddr - 0x402000 + 0x2000
    elif 0x403db8 <= vaddr < 0x403db8 + 0x237af0:
        return vaddr - 0x403db8 + 0x2db8
    else:
        return None

# Dispatch table at 0x4040e0
dispatch_table_offset = vaddr_to_fileoff(0x4040e0)
print(f"Dispatch table file offset: 0x{dispatch_table_offset:x}")

dispatch_table = []
for i in range(18):
    addr = struct.unpack("<Q", data[dispatch_table_offset + i*8:dispatch_table_offset + i*8 + 8])[0]
    dispatch_table.append(addr)
    print(f"Opcode {i}: 0x{addr:x}")
